  'ngsl-1638': { example: 'I do my homework at the desk in my room.', exampleCs: 'Úkoly dělám u psacího stolu ve svém pokoji.' }, // desk
  'ngsl-1639': { example: 'You need a permit to park your car here.', exampleCs: 'K parkování tady potřebujete povolení.' }, // permit
  'ngsl-1640': { example: 'You should take your health more seriously.', exampleCs: 'Měl bys brát své zdraví vážněji.' }, // seriously
  'ngsl-1641': { example: 'We saw wild horses in the national park.', exampleCs: 'V národním parku jsme viděli divoké koně.' }, // wild
