  'ngsl-1695': { example: 'Researchers found that teenagers need at least eight hours of sleep.', exampleCs: 'Výzkumníci zjistili, že teenageři potřebují alespoň osm hodin spánku.' }, // researcher
  'ngsl-1696': { example: 'It was just an ordinary day at school.', exampleCs: 'Byl to jen obyčejný den ve škole.' }, // ordinary
