  'ngsl-1709': { example: 'Can you give me some tips for the speaking exam?', exampleCs: 'Můžeš mi dát pár tipů na ústní zkoušku?' }, // tip
  'ngsl-1710': { example: 'Students get a 20 percent discount at the cinema.', exampleCs: 'Studenti mají v kině dvacetiprocentní slevu.' }, // discount
  'ngsl-1711': { example: 'We finally reached the peak after a four-hour climb.', exampleCs: 'Po čtyřhodinovém výstupu jsme konečně dosáhli vrcholu.' }, // peak
