  'ngsl-1716': { example: 'Please don\'t shout; I can hear you perfectly well.', exampleCs: 'Nekřič prosím, slyším tě úplně dobře.' }, // shout
  'ngsl-1717': { example: 'The children were playing in the school yard during the break.', exampleCs: 'Děti si o přestávce hrály na školním dvoře.' }, // yard
  'ngsl-1718': { example: 'The constant noise from the road makes it hard to sleep.', exampleCs: 'Kvůli neustálému hluku ze silnice se špatně spí.' }, // constant
  'ngsl-1719': { example: 'My marks have improved significantly since I joined a study group.', exampleCs: 'Od té doby, co chodím do studijní skupiny, se mé známky výrazně zlepšily.' }, // significantly
  'ngsl-1721': { example: 'Learning a new language takes a considerable amount of time.', exampleCs: 'Naučit se nový jazyk zabere značné množství času.' }, // considerable
  'ngsl-1722': { example: 'Read the instructions carefully before you start the test.', exampleCs: 'Než začneš psát test, pečlivě si přečti pokyny.' }, // instruction
  'ngsl-1723': { example: 'Dolphins are famous for their high intelligence.', exampleCs: 'Delfíni jsou známí svou vysokou inteligencí.' }, // intelligence
  'ngsl-1724': { example: 'The weather was ideal for a day at the beach.', exampleCs: 'Počasí bylo na den na pláži ideální.' }, // ideal
