  'ngsl-1729': { example: 'The film was somewhat longer than I expected.', exampleCs: 'Film byl poněkud delší, než jsem čekal.' }, // somewhat
  'ngsl-1730': { example: 'She gave her grandmother a kiss on the cheek.', exampleCs: 'Dala babičce pusu na tvář.' }, // kiss
  'ngsl-1731': { example: 'Tomorrow I have to give a presentation about recycling.', exampleCs: 'Zítra musím mít prezentaci o recyklaci.' }, // presentation
  'ngsl-1732': { example: 'This project is a joint effort by the whole class.', exampleCs: 'Tento projekt je společným dílem celé třídy.' }, // joint
  'ngsl-1733': { example: 'Twenty schools will compete in the national chess tournament.', exampleCs: 'V celostátním šachovém turnaji bude soutěžit dvacet škol.' }, // compete
  'ngsl-1734': { example: 'A poll showed that most students want a longer lunch break.', exampleCs: 'Průzkum ukázal, že většina studentů chce delší polední přestávku.' }, // poll
