  'ngsl-1748': { example: 'Cut the bread into thin slices, please.', exampleCs: 'Nakrájej prosím chleba na tenké plátky.' }, // thin
  'ngsl-1749': { example: 'We had to rush to catch the last bus home.', exampleCs: 'Museli jsme spěchat, abychom stihli poslední autobus domů.' }, // rush
